uniform float speed : 0.0 .. 2.0 = 0.25;
uniform float sat : 0.0 .. 1.0 = 0.85;
uniform float height : 0.05 .. 1.0 = 0.35;

state fixed rot;
state fixed drift;
state fixed satf;
state fixed hf;

void update() {
  rot = fract(rot + fixed(dt * speed * 0.05));
  drift = fract(drift + fixed(dt * speed * 0.02));
  satf = fixed(sat);
  hf = fixed(height);
}

vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed h = fract(ang + rot + fixed(led.pos.y) * hf + drift);
  return hsv2rgb(h, satf, fixed(1.0));
}
